878	      // is shortened, the one documented test seam `chat_cubit.dart`'s
879	      // own constructor comment calls out ("production never passes
880	      // anything else"). Closed explicitly below since it was never
881	      // registered with `sl`, so `resetCoreDependencies()` never disposes
882	      // it.
883	      final cubit = ChatCubit(
884	        sl<ChatRepository>(),
885	        sl<ConnectivityWatcher>(),
886	        sl<SaveChatMessageAsEntryUseCase>(),
887	        insightInactivityTimeout: const Duration(milliseconds: 30),
888	      );
889	      await cubit.init();
890	
891	      await emitConnectivity(['none']);
892	      expect((cubit.state as ChatReady).isOffline, isTrue);
893	
894	      // Long enough for the short inactivity timer above to have fired
895	      // at least once for real.
896	      await Future<void>.delayed(const Duration(milliseconds: 100));
897	
898	      expect(
899	        adapter.requests.where((r) => r.path.contains('chat-insight-create')),
900	        isEmpty,
901	      );
902	      expect((cubit.state as ChatReady).activeInsight, isNull);
903	
904	      await cubit.close();
905	    },
906	  );
907	
908	  test(
909	    'spec-6-5: dismissInsight() clears ChatReady.activeInsight with no '
910	    'further request ever reaching the real transport -- no dismiss '
911	    'endpoint exists in the contract (Boundaries)',
912	    () async {
913	      adapter.queueJsonResponse(200, {'data': <dynamic>[]});
914	      adapter.queueJsonResponse(200, {
915	        'data': _sessionJson(id: 'session-1', updatedAt: '2026-01-01T00:00:00Z'),
916	      });
917	      adapter.queueJsonResponse(200, {'data': <dynamic>[]});
918	
919	      final cubit = sl<ChatCubit>();
920	      await cubit.init();
921	
922	      for (var i = 0; i < 4; i++) {
923	        _queuePlainReply(adapter, 'Resposta $i.');
924	        await cubit.sendMessage('Mensagem $i');
925	      }
926	      adapter.queueResponseForPath(
927	        'chat-insight-create',
928	        200,
929	        {
930	          'data': _insightJson(
931	            id: 'ins-1',
932	            sessionId: 'session-1',
933	            triggerType: 'message_count',
934	            status: 'ready',
935	            content: 'Um padrão notado.',
936	          ),
937	        },
938	      );
939	      _queuePlainReply(adapter, 'Resposta final.');
940	      await cubit.sendMessage('Mensagem final');
941	      for (var i = 0; i < 10; i++) {
942	        await Future<void>.delayed(Duration.zero);
943	      }
944	      expect((cubit.state as ChatReady).activeInsight, isNotNull);
945	
946	      final requestCountBeforeDismiss = adapter.requests.length;
947	      cubit.dismissInsight();
948	
949	      expect((cubit.state as ChatReady).activeInsight, isNull);
