        'data': {'jobId': 'job-2'},
      });
      adapter.queueJsonResponse(200, {
        'data': _statusJson(
          jobId: 'job-2',
          status: 'done',
          narrativeStatus: 'failed',
        ),
      });

      final cubit = sl<ExportJobCubit>();
